/* hamburger-aasta menu */
.hamburger-aasta {
    padding: 0;
    margin: 0;
    height: 25px;
    width: 25px;
    text-align: center;
    background-color: transparent;
}

.hamburger-aasta:not(.close) {
    position: absolute;
    top: 10px;
    right: 20px;
    /****Eng.mohamed : z-index:999***/
    z-index: 9;
    border: 0;
    display: none;
    width: auto;
    height: auto;
    border: 1px solid #a4a3a3;
    border-radius: 2px;
    /****Eng.mohamed :padding:10px***/
    padding: 7px;
    direction: rtl;
}

.hamburger-aasta:hover,
.hamburger-aasta:focus {
    background-color: transparent;
    outline: none;
}

.hamburger-aasta .line {
    /*******8Eng.mohamed* 50px****/
    width: 30px;
    /*******8Eng.mohamed* 4px****/
    height: 3px;
    background-color: #3c3c3b;
    display: block;
    /*******8Eng.mohamed* 10px****/
    margin: 7px 0;
    transition: all 0.4s ease-in;
    right: 0;
    position: revert;
}

.hamburger-aasta:hover {
    cursor: pointer;
}

.hamburger-aasta.close {
    padding: 10px;
}

.hamburger-aasta.close .wrap {
    position: relative;
    width: 30px;
    height: 30px;
    display: block;
}

.hamburger-aasta.close .line {
    margin: 0;
    width: 100%;
    position: absolute;
    top: calc(50% - 2px);
    transform: rotate(45deg);
    background-color: #000;
}

.hamburger-aasta.close .line:last-child {
    transform: rotate(-45deg);
}

.hamburger-aasta.is-active .line:nth-child(1) {
    transform: rotate(45deg);
    position: absolute;
    left: 0;
    top: 5px;
}

.hamburger-aasta.is-active .line:nth-child(2) {
    opacity: 0;
    visibility: hidden;
    position: absolute;
    transition: none;
}

.hamburger-aasta.is-active .line:nth-child(3) {
    transform: rotate(-45deg);
    position: absolute;
    left: 0;
    top: 5px;
}

#menu-aast {
