    transition: transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55),
        -webkit-transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
    transition-delay: 0.2s;
    overflow-x: hidden;
    overflow-y: auto;
}

