/* drop-down */
.nav-aast ul li ul {
    position: absolute;
    top: calc(100%);
    left: 0;
    margin: 0;
    z-index: 4;
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
    transition: 0.3s;
    box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
    min-width: 300px;
}

.nav-aast ul li ul li {
    position: relative;
    display: flex;
    padding: 0;
    margin-bottom: 0;
}

.nav-aast ul li ul li:last-child > a {
    border-bottom: none;
}

.nav-aast ul li ul ul {
    position: absolute;
    left: 0px;
    top: 100%;
    left: 100%;
    top: 0;
}

.nav-aast ul li ul li a {
    padding: 5px 24px 5px 5px;
    width: 100%;
    display: block;
    font-size: 16px;
    background-color: #f9f9f9;
